using DSWI_T1_1.Data;using DSWI_T1_1.Models;using DSWI_T1_1.Repositories.Interfaces;using Microsoft.EntityFrameworkCore;using Microsoft.Data.SqlClient;using System.Data;namespace DSWI_T1_1.Repositories.Implementations; public class PacienteRepository:IPacienteRepository{private readonly ClinicaDbContext db;public PacienteRepository(ClinicaDbContext c)=>db=c;public async Task<IReadOnlyList<Paciente>> ObtenerTodosAsync()=>await db.Pacientes.FromSqlRaw("EXEC dbo.usp_Pacientes_Listar").AsNoTracking().ToListAsync();public async Task<Paciente?> ObtenerPorIdAsync(int id){var lista=await db.Pacientes.FromSqlInterpolated($"EXEC dbo.usp_Pacientes_ObtenerPorId @PacienteID={id}").AsNoTracking().ToListAsync();return lista.FirstOrDefault();}public async Task<int> CrearAsync(Paciente p){var id=new SqlParameter("@NuevoID",SqlDbType.Int){Direction=ParameterDirection.Output};await db.Database.ExecuteSqlInterpolatedAsync($"EXEC dbo.usp_Pacientes_Crear @Nombre={p.Nombre},@DNI={p.DNI},@NuevoID={id} OUTPUT");return id.Value==DBNull.Value?0:(int)id.Value;}public async Task<bool> EditarAsync(Paciente p){await db.Database.ExecuteSqlInterpolatedAsync($"EXEC dbo.usp_Pacientes_Editar @PacienteID={p.PacienteID},@Nombre={p.Nombre},@DNI={p.DNI}");return true;}}